function truncate(input, maxLength, suffix = '…', { wordBoundary = false } = {}) {
  const s = String(input);
  if (s.length <= maxLength) return s;
  const head = s.slice(0, Math.max(0, maxLength - suffix.length));
  if (!wordBoundary) return head + suffix;
  // Cut back to the last word boundary that still fits. If not even the first word fits there
  // is no such boundary, so all that is left to return is the suffix.
  const lastSpace = head.search(/\s+\S*$/);
  return (lastSpace === -1 ? '' : head.slice(0, lastSpace)) + suffix;
}

