// Reduce markdown to the words a reader actually sees: link text stays and the URL goes, and
// emphasis markers, heading hashes and list bullets disappear.
function stripMarkdown(input) {
  return String(input)
    .replace(/!?\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/^[ \t]*#{1,6}[ \t]+/gm, '')
    .replace(/^[ \t]*(?:[*+-]|\d+\.)[ \t]+/gm, '')
    .replace(/\*+|_+|~~|`+/g, '');
}

function wordCount(input) {
  const s = stripMarkdown(input).trim();
  if (!s) return 0;
  return s.split(/\s+/).filter(Boolean).length;
}

