} = require('../src/text');

test('slugify transliterates Cyrillic', () => {
  assert.strictEqual(slugify('Привет мир'), 'privet-mir');
  assert.strictEqual(slugify('Ёжик, ЩИ и объём'), 'ezhik-shchi-i-obem');
  // Latin behaviour unchanged
  assert.strictEqual(slugify('Hello World'), 'hello-world');
});

test('truncate can cut on a word boundary', () => {
  assert.strictEqual(truncate('the quick brown fox', 12, '…', { wordBoundary: true }), 'the quick…');
  // the word ends exactly where the budget does — keep it
  assert.strictEqual(truncate('the quick brown', 10, '…', { wordBoundary: true }), 'the quick…');
  // no trailing whitespace before the suffix
  assert.strictEqual(truncate('the quick brown', 11, '…', { wordBoundary: true }), 'the quick…');
  // nothing to keep: not even the first word fits
  assert.strictEqual(truncate('supercalifragilistic', 5, '…', { wordBoundary: true }), '…');
  // default behaviour unchanged, with and without an options object
  assert.strictEqual(truncate('the quick brown fox', 12), 'the quick b…');
  assert.strictEqual(truncate('the quick brown fox', 12, '…', {}), 'the quick b…');
  assert.strictEqual(truncate('short', 20, '…', { wordBoundary: true }), 'short');
});

test('wordCount counts the words a reader sees, not markdown syntax', () => {
  assert.strictEqual(wordCount('**bold** text'), 2);
  assert.strictEqual(wordCount('a [link text](https://example.com/page) here'), 4);
  assert.strictEqual(wordCount('# Heading here'), 2);
  assert.strictEqual(wordCount('- item one\n- item two'), 4);
  // an ordered-list number is a bullet too, so it is not a word
  assert.strictEqual(wordCount('1. first\n2. second'), 2);
  assert.strictEqual(
    wordCount(
      '# Heading here\nSome **bold** and *italic* text with a [link text](https://example.com/page)\n- item one\n- item two'
    ),
    15
  );
  assert.strictEqual(wordCount('**'), 0);
  // plain text is unaffected
  assert.strictEqual(wordCount('one two three'), 3);
  assert.strictEqual(wordCount('   '), 0);
});

test('readingTime reports whole minutes at 200 wpm', () => {
  assert.strictEqual(readingTime(''), 0);
  assert.strictEqual(readingTime('   '), 0);
  assert.strictEqual(readingTime('one'), 1);
  const words = (n) => Array.from({ length: n }, (_, i) => 'w' + i).join(' ');
  assert.strictEqual(readingTime(words(200)), 1);
  assert.strictEqual(readingTime(words(201)), 2);
  assert.strictEqual(readingTime(words(600)), 3);
});

test('escapeHtml escapes the five characters without double-escaping', () => {
  assert.strictEqual(escapeHtml('&'), '&amp;');
  assert.strictEqual(escapeHtml('<'), '&lt;');
  assert.strictEqual(escapeHtml('>'), '&gt;');
  assert.strictEqual(escapeHtml('"'), '&quot;');
  assert.strictEqual(escapeHtml("'"), '&#39;');
  assert.strictEqual(
    escapeHtml('<a href="x">Tom & Jerry\'s</a>'),
    '&lt;a href=&quot;x&quot;&gt;Tom &amp; Jerry&#39;s&lt;/a&gt;'
  );
  // an ampersand already part of an entity is escaped once, not twice
  assert.strictEqual(escapeHtml('&amp;'), '&amp;amp;');
  assert.strictEqual(escapeHtml(''), '');
  assert.strictEqual(escapeHtml('plain text'), 'plain text');
});

{
  "cyrillic-slug": { "passes": true },
  "truncate-word-boundary": { "passes": true },
  "word-count-markdown": { "passes": true },
  "reading-time": { "passes": true },
  "escape-html": { "passes": true },
  "acronyms-configurable": { "passes": false },
  "excerpt": { "passes": false },
  "already-done-capitalize": { "passes": false }
}

