'use strict';

// Text utilities. Small on purpose: the interesting part is the backlog, not the code.

const ACRONYMS = new Set(['API', 'HTTP', 'SQL', 'URL', 'CSS']);

// Lowercase Cyrillic -> Latin. Soft and hard signs transliterate to nothing.
const CYRILLIC_TO_LATIN = {
  а: 'a', б: 'b', в: 'v', г: 'g', д: 'd', е: 'e', ё: 'e', ж: 'zh',
  з: 'z', и: 'i', й: 'y', к: 'k', л: 'l', м: 'm', н: 'n', о: 'o',
  п: 'p', р: 'r', с: 's', т: 't', у: 'u', ф: 'f', х: 'kh', ц: 'ts',
  ч: 'ch', ш: 'sh', щ: 'shch', ъ: '', ы: 'y', ь: '', э: 'e', ю: 'yu',
  я: 'ya',
};

function slugify(input) {
  return String(input)
    .trim()
    .toLowerCase()
    .replace(/[Ѐ-ӿ]/g, (ch) => CYRILLIC_TO_LATIN[ch] ?? '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function truncate(input, maxLength, suffix = '…', { wordBoundary = false } = {}) {
  const s = String(input);
  if (s.length <= maxLength) return s;
  const head = s.slice(0, Math.max(0, maxLength - suffix.length));
  if (!wordBoundary) return head + suffix;
  // `head` already ends at a boundary when the next character of the input is whitespace.
  if (/\s/.test(s[head.length])) return head.trimEnd() + suffix;
  // Otherwise drop the partial word at the end. If not even the first word fits, nothing is left
  // but the suffix.
  return head.replace(/\s*\S*$/, '') + suffix;
}

function capitalize(input) {
  const s = String(input);
  if (!s) return s;
  return s[0].toUpperCase() + s.slice(1);
}

// Reduce markdown to the words a reader actually sees: link text stays and the URL goes, and
// emphasis markers, heading hashes and list bullets disappear.
function stripMarkdown(input) {
  return String(input)
    .replace(/!?\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/^[ \t]*#{1,6}[ \t]+/gm, '')
    .replace(/^[ \t]*(?:[*+-]|\d+\.)[ \t]+/gm, '')
    .replace(/\*+|_+|~~|`+/g, '');
}

function wordCount(input) {
  const s = stripMarkdown(input).trim();
  if (!s) return 0;
  return s.split(/\s+/).filter(Boolean).length;
}

// `&` first: escaping it after the others would turn `&lt;` into `&amp;lt;`.
function escapeHtml(input) {
  return String(input)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const WORDS_PER_MINUTE = 200;

function readingTime(input) {
  const words = wordCount(input);
  if (!words) return 0;
  return Math.max(1, Math.ceil(words / WORDS_PER_MINUTE));
}

// `acronyms` is any iterable of strings (Set or array) and replaces the built-in list when given.
function titleCase(input, acronyms = ACRONYMS) {
  const known = new Set(Array.from(acronyms, (a) => String(a).toUpperCase()));
  return String(input)
    .split(/\s+/)
    .map((w) => (known.has(w.toUpperCase()) ? w.toUpperCase() : capitalize(w.toLowerCase())))
    .join(' ');
}

module.exports = {
  slugify,
  truncate,
  capitalize,
  wordCount,
  escapeHtml,
  readingTime,
  titleCase,
  ACRONYMS,
};

